--
-- Table structure for table `applications`
--

DROP TABLE IF EXISTS `applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `applications` (
  `application_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `applicant_id` bigint unsigned NOT NULL,
  `scholarship_program` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scholarship_year` smallint unsigned NOT NULL,
  `academic_average` decimal(5,2) NOT NULL,
  `monthly_income` decimal(12,2) NOT NULL,
  `mswdo_poverty_eligible` tinyint(1) NOT NULL DEFAULT '0',
  `household` int unsigned NOT NULL,
  `children_count` int unsigned NOT NULL DEFAULT '0',
  `senior_count` int unsigned NOT NULL DEFAULT '0',
  `pwd_count` int unsigned NOT NULL DEFAULT '0',
  `solo_parent` tinyint(1) NOT NULL DEFAULT '0',
  `dependent` tinyint(1) NOT NULL DEFAULT '0',
  `exam_score` decimal(5,2) DEFAULT NULL,
  `exam_passed` tinyint(1) NOT NULL DEFAULT '0',
  `four_ps_beneficiary` tinyint(1) NOT NULL DEFAULT '0',
  `spes_beneficiary` tinyint(1) NOT NULL DEFAULT '0',
  `scholars_in_family` int unsigned NOT NULL DEFAULT '0',
  `residency` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `previous_scholarship` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('DRAFT','SUBMITTED','UNDER_REVIEW','FOR_INTERVIEW','INTERVIEWED','RECOMMENDED','APPROVED','REJECTED','WAITLISTED','WITHDRAWN') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `encoded_by` bigint unsigned DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_archived` tinyint(1) NOT NULL DEFAULT '0',
  `dependents_count` int unsigned NOT NULL DEFAULT '0',
  `exam_raw_score` int unsigned DEFAULT NULL,
  `exam_total_items` int unsigned DEFAULT NULL,
  PRIMARY KEY (`application_id`),
  UNIQUE KEY `uq_applicant_program_year` (`applicant_id`,`scholarship_program`,`scholarship_year`),
  KEY `fk_application_encoder` (`encoded_by`),
  KEY `idx_application_status` (`status`),
  KEY `idx_application_year` (`scholarship_year`),
  KEY `idx_application_applicant` (`applicant_id`),
  CONSTRAINT `fk_application_applicant` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`applicant_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_application_encoder` FOREIGN KEY (`encoded_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_academic_average` CHECK ((`academic_average` between 0 and 100)),
  CONSTRAINT `chk_exam_score` CHECK (((`exam_score` is null) or (`exam_score` between 0 and 100))),
  CONSTRAINT `chk_household_counts` CHECK ((((`children_count` + `senior_count`) + `pwd_count`) <= `household`)),
  CONSTRAINT `chk_household_size` CHECK ((`household` >= 1)),
  CONSTRAINT `chk_monthly_income` CHECK ((`monthly_income` >= 0)),
  CONSTRAINT `chk_scholarship_year` CHECK ((`scholarship_year` between 2000 and 2200))
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
